UPDATE kids_own.tb_cm_m_uld_prst
SET ver_info_nm    = #{verInfoNm}
, last_updt_ymd  = #{lastUpdtYmd}
, updt_cycle_cnt = #{updtCycleCnt}
, mdfr_id        = #{mdfrId}
, mdfcn_dt       = NOW()
WHERE ptcp_inst_sn = #{ptcpInstSn}
AND pblnt_sn     = #{pblntSn}
AND (del_yn IS NULL OR del_yn = 'N')

UPDATE kids_own.tb_cm_m_uld_prst
SET ver_info_nm    = #{verInfoNm}
, uld_type_cd     = '02'
, uld_inst_prgrs_stts_cd = CASE
    WHEN uld_inst_prgrs_stts_cd IN ('03','04') THEN uld_inst_prgrs_stts_cd
    ELSE '03'
  END
, ptcp_cmptn_dt = CASE
    WHEN uld_inst_prgrs_stts_cd IN ('03','04') THEN ptcp_cmptn_dt
    ELSE NOW()
  END
, last_updt_ymd  = #{lastUpdtYmd}
, updt_cycle_cnt = #{updtCycleCnt}
, mdfr_id        = #{mdfrId}
, mdfcn_dt       = NOW()
WHERE ptcp_inst_sn = #{ptcpInstSn}
AND pblnt_sn     = #{pblntSn}
AND (del_yn IS NULL OR del_yn = 'N')

mapper.select:
SELECT A.uld_prd_sn AS uldPrdSn , A.pblnt_sn AS pblntSn , A.ptcp_inst_sn AS ptcpInstSn , A.trsf_se_cd AS trsfSeCd , A.tbl_se_cd AS tblSeCd , A.tnocs AS tnocs , A.bgng_ymd AS bgngYmd , A.end_ymd AS endYmd , A.del_yn AS delYn , A.rgtr_id AS rgtrId , TO_CHAR(A.reg_dt, 'YYYY-MM-DD HH24:MI:SS') AS regDt , A.mdfr_id AS mdfrId , TO_CHAR(A.mdfcn_dt, 'YYYY-MM-DD HH24:MI:SS') AS mdfcnDt FROM kids_own.tb_cm_d_uld_prd_scl A WHERE (A.del_yn IS NULL OR A.del_yn = 'N')
AND A.pblnt_sn = #{pblntSn}
AND A.ptcp_inst_sn = #{ptcpInstSn}
AND A.tbl_se_cd = #{tblSeCd}
AND A.trsf_se_cd = #{trsfSeCd}
ORDER BY A.uld_prd_sn ASC

mapper.update:
UPDATE kids_own.tb_cm_d_uld_prd_scl
ptcp_inst_sn = #{ptcpInstSn}, trsf_se_cd = #{trsfSeCd}, tbl_se_cd = #{tblSeCd}, tnocs = #{tnocs}, bgng_ymd = #{bgngYmd}, end_ymd = #{endYmd}, mdfr_id = #{mdfrId}, mdfcn_dt = NOW()
WHERE uld_prd_sn = #{uldPrdSn} AND pblnt_sn = #{pblntSn}

UPDATE kids_own.tb_cm_d_uld_prd_scl
SET del_yn   = 'Y'
, mdfr_id  = COALESCE(#{mdfrId}, '관리자')
, mdfcn_dt = NOW()
WHERE uld_prd_sn = #{uldPrdSn}
AND pblnt_sn   = #{pblntSn}

